(* Fixed records read as bits of 8-byte big-endian words. *)

(* A field read as bits of the big-endian 8-byte word at [q] in its record:
   the word shifted left by [l], then right by [r] keeping its sign, then
   masked by [m], all ones for a signed field. Every field of the record reads
   this way or none does, so a decode makes no dispatch and no call. *)
type word = { q : int; l : int; r : int; m : int; same : bool }

type (_, _) words =
  | WNil : ('r, 'r) words
  | WCons :
      word * ('a, int) Type.eq * ('rest, 'result) words
      -> ('a -> 'rest, 'result) words

external get64u : bytes -> int -> int64 = "%caml_bytes_get64u"
external swap64 : int64 -> int64 = "%bswap_int64"

(* The word through the compiler's own load, which boxes nothing even where
   this module cannot inline the runtime's; the [paranoid] profile checks its
   bounds first. *)
let[@inline] load buf base q =
  let p = base + q in
  if Unchecked.checked && (p < 0 || p > Bytes.length buf - 8) then
    invalid_arg "index out of bounds";
  let w = get64u buf p in
  if Sys.big_endian then w else swap64 w

let[@inline] bits w l r m =
  Int64.to_int (Int64.shift_right (Int64.shift_left w l) r) land m

let rec bit_width m = if m = 0 then 0 else 1 + bit_width (m lsr 1)

(* The word of a field whose [bytes] bytes at [o] hold [w] bits above bit
   [s], in a record of [size] bytes. *)
let word ~size o ~bytes ~s ~w ~signed =
  let aligned = o - (o mod 8) in
  let q =
    if o + bytes <= aligned + 8 && aligned + 8 <= size then aligned
    else min o (size - 8)
  in
  let low = 64 - (8 * (o + bytes - q)) in
  {
    q;
    l = 64 - low - s - w;
    r = 64 - w;
    m = (if signed then -1 else (1 lsl w) - 1);
    same = false;
  }

